(7411691, 1168331, 2553, '<td valign="top">I like this a lot... I can totally see it as an advertisement.</td>', 'I like this a lot... I can totally see it as an advertisement.', '2015-10-22 17:43:24.000000', NULL, 1),
(7411692, 1168267, 2553, '<td valign="top">At first look, all the crazy spray painting made it look like it had some kind of post processed "look", but looking at it further I feel like it is just the perfect composition of color, texture, patterns and light and dark.  Very nicely seen, I enjoy it!</td>', 'At first look, all the crazy spray painting made it look like it had some kind of post processed "look", but looking at it further I feel like it is just the perfect composition of color, texture, patterns and light and dark.  Very nicely seen, I enjoy it!', '2015-10-22 17:50:28.000000', NULL, 1),
